const applyPlanned=(x:Project,m:Planned):Project=>({...x,planId:m.id,name:m.name||x.name,number:m.number||x.number,orderNumber:m.orderNumber||x.orderNumber,customer:m.customer||x.customer,address:m.address||x.address,foremanName:m.foreman||x.foremanName,contact:m.foreman||x.contact,contactPersons:m.contacts.length?m.contacts.map(c=>({id:randomId(),...c})):x.contactPersons});
const blankReport=(p:Project,week:string,area:string,kind:ReportKind='measurement'):Report=>{const date=weekOf(today())===week?today():weekStart(week);return{kind,clientDraftId:randomId(),...(kind!=='measurement'?{timeSheet:{mode:'day' as const,anchorDate:date,factor:p.factor,entries:[]}}:{}),id:'',projectId:p.id,date,endDate:date,team:'',author:p.foremanName||'',area:'',note:'',lines:[],state:'draft',review:'pending',reviewNote:'',createdAt:'',updatedAt:'',sentAt:null,deadline:null};};
function Field({label,children,hint,wide=false}:{label:string;children:ReactNode;hint?:string;wide?:boolean}){return <label className={'field'+(wide?' wide':'')}><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>;}
function Empty({title,text,children}:{title:string;text:string;children?:ReactNode}){return <div className="empty"><ClipboardList size={34}/><h3>{title}</h3><p>{text}</p>{children}</div>;}
function Status({r,closed}:{r:Report;closed:boolean}){return <Badge className={'status '+(r.review==='approved'?'green':r.review==='changes'?'orange':r.state==='draft'?'grey':'violet')}>{r.review==='approved'?<><Check size={12}/>Geprüft</>:r.review==='changes'?'Änderung angefragt':closed?<><Lock size={12}/>Woche zu</>:r.state==='ready'?'Fertig':'Entwurf'}</Badge>;}


