 useEffect(()=>{let live=true;const saved=localStorage.getItem('daso-aufmass-project')||'';fetch('/api/data'+(saved?'?project='+encodeURIComponent(saved):''),{cache:'no-store'}).then(r=>r.json().then(raw=>{const j=raw as Data & {error:string};if(!r.ok)throw Error(j.error);return j;})).then((j:Data)=>{if(!live)return;setData(j);setProjectId(j.projects.some(p=>p.id===saved)?saved:(j.projects.find(p=>!p.archivedAt)||j.projects[0])?.id||'');}).catch(e=>live&&setError(e.message)).finally(()=>live&&setLoading(false));return()=>{live=false;};},[]);
 useEffect(()=>{if(!projectId)return;localStorage.setItem('daso-aufmass-project',projectId);setArea('');setLoading(true);load(projectId).catch(e=>setError(e.message)).finally(()=>setLoading(false));},[projectId]);
 const[showArchived,setShowArchived]=useState(false);const[planList,setPlanList]=useState<Planned[]>([]);useEffect(()=>{fetch('/api/plan').then(r=>r.json() as Promise<{projects?:Planned[]}>).then(j=>setPlanList(j.projects||[])).catch(()=>{});},[data.projects.length]);const unlinked=planList.filter(m=>!data.projects.some(p=>p.planId===m.id||(!p.planId&&((m.number&&p.number===m.number)||p.name.trim().toLowerCase()===m.name.trim().toLowerCase()))));const[role,setRole]=useState(''),[meName,setMeName]=useState(''),[menuOpen,setMenuOpen]=useState(false);useEffect(()=>{fetch('/api/me').then(r=>r.json() as Promise<{role?:string;name?:string}>).then(j=>{setRole(j.role||'');setMeName(j.name||'');}).catch(()=>{});},[]);const visibleProjects=data.projects.filter(p=>!p.archivedAt||showArchived||p.id===projectId);
 const perform:Perform=async(action,payload={})=>{setBusy(true);setError('');setNotice('');try{const r=await fetch('/api/data',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,projectId,...payload})});const j=await r.json() as {id:string;ok?:boolean;reusedDraft?:boolean;position?:Position;error:string};if(!r.ok)throw Error(j.error);if(action==='saveProject'&&!projectId&&j.id)setProjectId(j.id);await load(action==='saveProject'&&j.id?j.id:projectId);setNotice('Gespeichert.');return j;}catch(e){setError(e instanceof Error?e.message:'Speichern fehlgeschlagen.');return null;}finally{setBusy(false);}};
 async function work(fn:()=>Promise<void>){setBusy(true);setError('');try{await fn();}catch(e){setError(e instanceof Error?e.message:'Aktion fehlgeschlagen.');}finally{setBusy(false);}}
 async function upload(file:File,kind:StoredFile['kind'],reportId=''){if(!project)throw Error('Projekt fehlt.');const prepared=kind==='attachment'?await attachmentOrientation.prepare(file):{file,normalized:false};const f=new FormData();f.set('projectId',project.id);f.set('reportId',reportId);f.set('kind',kind);f.set('file',prepared.file);if(prepared.normalized)f.set('orientationNormalized','1');if('original' in prepared&&prepared.original)f.set('originalFile',prepared.original);const r=await fetch('/api/files',{method:'POST',body:f});const j=await r.json() as StoredFile & {error:string};if(!r.ok)throw Error(j.error);await load();return j;}
 async function refreshDrafts(){if(projectId)setBrowserDrafts(await readBrowserDrafts(projectId));}
 useEffect(()=>{if(!projectId)return;let live=true;const refresh=()=>readBrowserDrafts(projectId).then(drafts=>live&&setBrowserDrafts(drafts));void refresh();const storage=(event:StorageEvent)=>{if(event.key?.startsWith('daso-report-draft-v1:'))void refresh();};window.addEventListener('storage',storage);return()=>{live=false;window.removeEventListener('storage',storage);};},[projectId]);
 async function openReport(report:Report,day?:string){setReportDay(day);const drafts=await readBrowserDrafts(projectId),draft=drafts.find(d=>report.id?d.report.id===report.id:d.key===report.clientDraftId);setReportSession(randomId());setResumeDraft(report.state==='draft'?draft||null:null);setReportEdit(report);}
 function newReport(){if(!project)return;setReportSession(randomId());setReportDay(undefined);setResumeDraft(null);setReportEdit(blankReport(project,week,area,reportType));}
 async function closeReport(){const parentId=reportEdit?.parentReportId;setResumeDraft(null);if(parentId){try{const fresh=await load(),parent=fresh.reports.find(r=>r.id===parentId);if(parent)await openReport(parent);else setReportEdit(null);}catch(e){setError(e instanceof Error?e.message:'Aufmaß konnte nicht geöffnet werden.');setReportEdit(null);}}else setReportEdit(null);void refreshDrafts();}
