function DailyReports({allReports,company,reports,project,files,closed,busy,open,work}:{allReports:Report[];company?:CompanyProfile;reports:Report[];project:Project;files:StoredFile[];closed:boolean;busy:boolean;open:(r:Report,day?:string)=>void;work:(fn:()=>Promise<void>)=>Promise<void>}){return <div className="daily-groups">{dailyTeams(reports,project.factor).map(day=><section key={day.date+'|'+day.endDate} className="daily-group"><div className="day-heading"><h3>{new Date(day.date+'T12:00:00Z').toLocaleDateString('de-DE',{weekday:'long',day:'2-digit',month:'2-digit',year:'numeric',timeZone:'UTC'})}{day.endDate!==day.date?' bis '+dateLabel(day.endDate):''}</h3><span>{day.teams.length} {day.teams.length===1?'Team':'Teams'}</span></div><div className="table-scroll"><Table className="mobile-records report-records" aria-label="Berichte je Team und Tag"><TableHeader><TableRow><TableHead>Team / Mitarbeiter</TableHead><TableHead className="numeric">Tagesumsatz in €</TableHead>{reports.some(hasContractors)&&<><TableHead className="numeric">Nachunternehmerkosten</TableHead><TableHead className="numeric">Gewinn</TableHead></>}<TableHead>Aufmaße</TableHead><TableHead>Anlagen</TableHead><TableHead>Aktion</TableHead></TableRow></TableHeader><TableBody>{day.teams.map(team=>{const configured=project.teams?.find(t=>t.code===team.team),snapshots=team.reports.map(r=>r.teamWork).filter(Boolean),companies=[...new Set(snapshots.length?snapshots.map(w=>w!.company):[configured?.company||''])].filter(Boolean),names=[...new Set(snapshots.length?snapshots.flatMap(w=>w!.workers.map(p=>p.name)):configured?.employees||[])].filter(Boolean);return <TableRow key={team.team}><TableCell className="record-identity"><strong className="team-day-label">{team.team}</strong>{companies.length>0&&<small>{companies.join(', ')}</small>}{names.length>0&&<small>{names.join(' · ')}</small>}<EmployeeBreakdown reports={team.reports} factor={project.factor}/><small>Erfasst von: {[...new Set(team.reports.map(r=>r.author).filter(Boolean))].join(', ')||'—'}</small></TableCell><TableCell className="numeric team-day-value" data-label="Tagesumsatz in €">{team.reports.some(timeRevenueAvailable)?money(team.employee):'—'}{!team.reports.every(timePricingComplete)&&team.reports.some(timeRevenueAvailable)&&<small>Vorläufig · Sätze ergänzen</small>}</TableCell>{reports.some(hasContractors)&&<><TableCell className="numeric" data-label="Nachunternehmerkosten">{team.reports.every(r=>!!r.teamWork)&&team.cost!==null?money(team.cost):'—'}</TableCell><TableCell className="numeric" data-label="Gewinn"><strong className={team.profit!==null&&team.profit<0?'overdue':'green-text'}>{team.reports.every(r=>!!r.teamWork)&&team.profit!==null?money(team.profit):'—'}</strong>{team.missingHours>0&&<small>Stunden nicht vollständig</small>}</TableCell></>}<TableCell data-label="Berichte">{team.reports.map(r=><div className="day-report-status" key={r.id}><Status r={r} closed={closed}/>{isTimeReport(r)&&<small>{reportLabel(r)} · {qty2((r.timeSheet?.entries||[]).reduce((sum,entry)=>sum+(workMinutes(entry)||0),0)/60)} Std · {reportDateRange(r)}</small>}{r.state==='draft'&&<small>Im Tagesumsatz enthalten</small>}{r.endDate!==r.date&&<small>Zeitraum bis {dateLabel(r.endDate)}</small>}{r.sentAt&&<small>Versandt {dateLabel(r.sentAt)}</small>}</div>)}</TableCell><TableCell data-label="Anlagen">{files.filter(f=>team.reports.some(r=>reportBundle(r,allReports).some(item=>item.id===f.reportId))&&f.kind==='attachment').length}</TableCell><TableCell data-label="Öffnen / PDF"><div className="day-report-actions">{team.reports.map((r,i)=><div key={r.id} className="actions"><Button variant="outline" size="sm" onClick={()=>open(r,day.date)}>{team.reports.length>1?reportLabel(r)+' '+(i+1):'Öffnen'}</Button><Button variant="ghost" size="icon" disabled={busy} aria-label={'PDF '+day.date+' '+team.team+' Aufmaß '+(i+1)} onClick={()=>work(async()=>{const source=reports.find(original=>original.id===r.id)||r,document=isTimeReport(source)?timeDayReport(source,day.date)||source:source;const bundle=reportBundle(document,allReports),issue=bundleIssue(bundle,allReports);if(issue)throw Error(issue);download(await makePacket(project,bundle,files,undefined,company),bundleFileName(project,document,allReports),'application/pdf');})}><Download/></Button></div>)}</div></TableCell></TableRow>;})}</TableBody></Table></div></section>)}</div>;}

