function LVTable({positions}:{positions:Position[]}){const[q,setQ]=useState('');const found=matchPositions(positions,q);return <><div className="search-input"><Search size={17}/><Input value={q} onChange={e=>setQ(e.target.value)} placeholder="LV-Position oder Artikelbezeichnung suchen …" aria-label="LV durchsuchen"/></div>{positions.length?<div className="table-scroll lv-table"><Table className="mobile-records lv-records" aria-label="Leistungsverzeichnis"><TableHeader><TableRow><TableHead>LV-Position</TableHead><TableHead>Kurztext</TableHead><TableHead>EH</TableHead></TableRow></TableHeader><TableBody>{found.map(p=><TableRow key={p.id}><TableCell data-label="LV-Position" className="position-number">{p.number}</TableCell><TableCell data-label="Kurztext">{p.description}{p.isSupplement&&<small className="supplement-label">Nachtrag</small>}</TableCell><TableCell data-label="Einheit">{p.unit}</TableCell></TableRow>)}</TableBody></Table>{!found.length&&<p className="padding muted">Keine passenden Positionen.</p>}</div>:<p className="muted">Noch kein Kurztext-LV hinterlegt.</p>}<small className="muted">{Math.min(found.length,40)} von {positions.length} Positionen angezeigt.</small></>;}
